            // 【环境诊断】把关键 API 的真实情况显示在页面上
            function hpEnvDiag(){
                const L=[];
                let SG=null,CTX=null;
                try{ SG=window.SillyTavern||(window.top&&window.top.SillyTavern)||null; }catch(e){}
                try{ CTX=SG&&SG.getContext?SG.getContext():null; }catch(e){}
                const TH=window.TavernHelper||(window.top&&window.top.TavernHelper)||null;
                L.push('SillyTavern: '+(SG?'有':'无'));
                L.push('getContext: '+(CTX?'有':'无'));
                try{ L.push('loadWorldInfo: '+(CTX?typeof CTX.loadWorldInfo:'-')); }catch(e){ L.push('loadWorldInfo: 读取异常'); }
                let wn=null; try{ wn=CTX&&CTX.world_names; }catch(e){}
                L.push('world_names: '+(Array.isArray(wn)?('['+wn.length+'] '+(wn.slice(0,4).join(' / ')||'空')):'无'));
                let gs=null; try{ const pu=CTX&&(CTX.powerUser||CTX.power_user); gs=pu&&pu.world_info&&pu.world_info.globalSelect; }catch(e){}
                L.push('globalSelect: '+(Array.isArray(gs)?('['+gs.length+'] '+(gs.join(' / ')||'空')):'无'));
                L.push('TavernHelper: '+(TH?'有':'无'));
                if(TH){
                    const ks=Object.keys(TH).filter(function(k){ return /world|book|lore|entry/i.test(k); });
                    L.push('TH 相关方法: '+(ks.length?ks.join(', '):'（没有世界书相关方法）'));
                }
                let errs=window.__hpReadErr||'';
                if(errs) L.push('读取报错: '+errs);
                const kd=window.__hpKjDiag||[];
                if(kd.length) kd.forEach(function(x){ L.push('取名: '+x); });
                const bs=window.__hpBooks||[];
                L.push('取到书名 ('+bs.length+'): '+(bs.length?bs.join(' ｜ '):'（空）'));
                const ec=window.__hpEntryCounts||[];
                if(ec.length) ec.forEach(function(x){ L.push('条目: '+x); });
                return L;
            }
            function hpShowDiag(title){
                const hint=$('#char-lookup-hint');
                if(!hint) return;
